// Nonvisual, temporary reviewer input device. It dispatches manually requested
// events only to the review process's actual window, without global injection.
// No assertions, alternate visual components, automatic verdicts, or QtTest.
class PointerDriver : public QObject {
    Q_OBJECT
public:
    explicit PointerDriver(QObject *parent = nullptr) : QObject(parent) {}

    Q_INVOKABLE QString namedPoint(QObject *root, const QString &name) {
        QJsonObject result;
        auto *item = root ? root->findChild<QQuickItem *>(name) : nullptr;
        result["found"] = item != nullptr;
        if (item) {
            const QPointF point = item->mapToScene(QPointF(item->width()/2, item->height()/2));
            result["x"] = point.x(); result["y"] = point.y();
        }
        return QString::fromUtf8(QJsonDocument(result).toJson(QJsonDocument::Compact));
    }
    Q_INVOKABLE QString scrollInfo(QObject *root) {
        QJsonArray rows;
        if (!root) return QStringLiteral("[]");
        const auto objects = root->findChildren<QObject *>();
        for (QObject *o : objects) {
            const QString cls = QString::fromLatin1(o->metaObject()->className());
            if (!o->inherits("QQuickFlickable") && !cls.contains("ScrollView") && !cls.contains("TextArea")) continue;
            QJsonObject row;
            row["class"] = cls;
            row["objectName"] = o->objectName();
            row["parent"] = o->parent() ? QString::fromLatin1(o->parent()->metaObject()->className()) : QString();
            for (const char *key : {"width", "height", "implicitWidth", "implicitHeight", "contentWidth", "contentHeight", "contentY", "availableWidth", "availableHeight", "visible", "activeFocus", "interactive", "clip"}) {
                const QVariant value = o->property(key);
                if (value.isValid()) row[QString::fromLatin1(key)] = QJsonValue::fromVariant(value);
            }
            if (auto *item = qobject_cast<QQuickItem *>(o)) {
                const QPointF point = item->mapToScene(QPointF());
                row["sceneX"] = point.x(); row["sceneY"] = point.y();
            }
            rows.append(row);
        }
        return QString::fromUtf8(QJsonDocument(rows).toJson(QJsonDocument::Compact));
